pub(crate) fn t_rows(emon_t: i32) -> i32 {
    // Every row of the name table: a known kind and a value that is an ISO 15924 code (or a request name of a Chinese model).
    let n: i32 = 639;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut rows: i32 = 0;
    let t: &mut String = &mut crate::port::new_text();
    while i < n {
        j = i + 1;
        while OP_NAMES[(j) as usize] != 0 {
            j += 1;
        }
        crate::testport::assert_that(OP_NAMES[(i) as usize] >= 1, "kind from 1");
        crate::testport::assert_that(OP_NAMES[(i) as usize] <= 3, "to 3");
        if OP_NAMES[(i) as usize] == 3 {
            crate::testport::assert_that((OP_NAMES[(j + 1) as usize] == zh_chs()) || (OP_NAMES[(j + 1) as usize] == zh_cht()), "a request name");
        }
        if OP_NAMES[(i) as usize] != 3 {
            crate::testport::assert_eq(sc_emit_name(t, OP_NAMES[(j + 1) as usize]), 1, "an ISO 15924 code");
        }
        crate::testport::assert_that(j > (i + 1), "a name");
        rows += 1;
        i = j + 2;
    }
    crate::testport::assert_eq(rows, 74, "the rows of the three kinds");
    return 0;
}
